//! Fleet supervisor: auto-respawns workers when ready beads appear.
//!
//! The supervisor watches the global ready queue and heartbeat files to detect
//! when the fleet is idle (all workers exhausted) and new ready beads appear.
//! When both conditions are met, it spawns a new worker subject to the concurrency
//! cap and backoff to prevent rapid spawn/unspawn cycles.
//!
//! This is an opt-in daemon mode — the main `needle run` fleet respects exhaustion
//! and exits when idle. The supervisor is for always-on fleets that want to pick
//! up newly-added beads without manual intervention.
//!
//! Depends on: `config`, `health`, `types`, `telemetry`.

use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};

use anyhow::{Context, Result};
use chrono::{DateTime, Utc};

use crate::config::Config;
use crate::health::{HeartbeatData, HealthMonitor};
use crate::telemetry::Telemetry;
use crate::types::{BeadId, WorkerState};

// ──────────────────────────────────────────────────────────────────────────────
// Supervisor configuration
// ──────────────────────────────────────────────────────────────────────────────

/// Supervisor configuration derived from global config.
#[derive(Debug, Clone)]
pub struct SupervisorConfig {
    /// Interval between queue polls when fleet is active (seconds).
    ///
    /// When workers are actively processing beads, the supervisor polls at this
    /// interval to detect when the fleet goes idle.
    pub poll_interval_active_secs: u64,

    /// Interval between queue polls when fleet is idle (seconds).
    ///
    /// When all workers are exhausted, the supervisor polls at this longer
    /// interval to detect newly-added ready beads.
    pub poll_interval_idle_secs: u64,

    /// Maximum workers to spawn (concurrency cap).
    ///
    /// The supervisor will not spawn workers beyond this cap, even if ready
    /// beads exist. This defaults to the global `max_workers` config.
    pub max_workers: u32,

    /// Backoff after spawning a worker (seconds).
    ///
    /// After spawning a worker, the supervisor waits this long before
    /// considering another spawn. This prevents rapid spawn/unspawn cycles.
    pub spawn_backoff_secs: u64,

    /// Heartbeat directory to monitor.
    ///
    /// Path to the directory containing worker heartbeat files.
    pub heartbeat_dir: PathBuf,

    /// Workspace for spawning workers.
    ///
    /// The supervisor spawns workers into this workspace using `needle run`.
    pub workspace: PathBuf,

    /// Binary to use for spawning workers.
    ///
    /// Defaults to `needle` in PATH. Can be overridden for testing.
    pub needle_binary: PathBuf,

    /// Extra args to pass to spawned workers.
    ///
    /// Additional CLI arguments passed to each `needle run` invocation.
    pub worker_args: Vec<String>,
}

impl Default for SupervisorConfig {
    fn default() -> Self {
        SupervisorConfig {
            poll_interval_active_secs: 10,
            poll_interval_idle_secs: 30,
            max_workers: 4,
            spawn_backoff_secs: 60,
            heartbeat_dir: PathBuf::from(".needle/state/heartbeats"),
            workspace: PathBuf::from("."),
            needle_binary: PathBuf::from("needle"),
            worker_args: Vec::new(),
        }
    }
}

impl SupervisorConfig {
    /// Create supervisor config from global config.
    pub fn from_config(config: &Config) -> Self {
        let heartbeat_dir = config
            .health
            .heartbeat_dir
            .clone()
            .unwrap_or_else(|| PathBuf::from("state/heartbeats"));
        let heartbeat_dir = config.workspace.home.join(&heartbeat_dir);

        SupervisorConfig {
            poll_interval_active_secs: 10,
            poll_interval_idle_secs: 30,
            max_workers: config.worker.max_workers,
            spawn_backoff_secs: 60,
            heartbeat_dir,
            workspace: config.workspace.default.clone(),
            needle_binary: PathBuf::from("needle"),
            worker_args: Vec::new(),
        }
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Fleet state
// ──────────────────────────────────────────────────────────────────────────────

/// Summary of fleet state derived from heartbeat files.
#[derive(Debug, Clone)]
pub struct FleetState {
    /// Number of active workers (non-stale heartbeats with alive PIDs).
    pub active_count: usize,

    /// Number of idle workers (exhausted or no current bead).
    pub idle_count: usize,

    /// Number of workers currently processing beads.
    pub busy_count: usize,

    /// Whether all workers are idle (fleet is idle).
    pub is_idle: bool,

    /// Worker IDs of active workers.
    pub active_workers: Vec<String>,

    /// When this state was computed.
    pub computed_at: DateTime<Utc>,
}

impl FleetState {
    /// Empty fleet state (no heartbeats found).
    pub fn empty() -> Self {
        FleetState {
            active_count: 0,
            idle_count: 0,
            busy_count: 0,
            is_idle: true,
            active_workers: Vec::new(),
            computed_at: Utc::now(),
        }
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Ready queue result
// ──────────────────────────────────────────────────────────────────────────────

/// Result of checking the ready queue.
#[derive(Debug, Clone)]
pub struct ReadyQueueState {
    /// Number of ready beads found.
    pub ready_count: usize,

    /// IDs of ready beads (for telemetry).
    pub ready_beads: Vec<BeadId>,

    /// When the queue was checked.
    pub checked_at: DateTime<Utc>,
}

// ──────────────────────────────────────────────────────────────────────────────
// Supervisor
// ──────────────────────────────────────────────────────────────────────────────

/// Fleet supervisor: monitors ready queue and heartbeats, spawns workers.
///
/// The supervisor runs in a loop, polling the ready queue and reading heartbeat
/// files to decide when to spawn new workers. It respects the concurrency cap
/// and implements backoff to prevent rapid spawn/unspawn cycles.
pub struct Supervisor {
    config: SupervisorConfig,
    telemetry: Telemetry,
    shutdown: Arc<AtomicBool>,
    /// Last time a worker was spawned (for backoff).
    last_spawn: Arc<Mutex<Instant>>,
    /// Total workers spawned by this supervisor (for metrics).
    workers_spawned: Arc<AtomicU32>,
}

use std::sync::Mutex;

impl Supervisor {
    /// Create a new supervisor.
    ///
    /// # Arguments
    ///
    /// * `config` - Supervisor configuration
    /// * `telemetry` - Telemetry emitter
    /// * `shutdown` - Shared shutdown flag (set by signal handlers)
    pub fn new(
        config: SupervisorConfig,
        telemetry: Telemetry,
        shutdown: Arc<AtomicBool>,
    ) -> Self {
        Supervisor {
            config,
            telemetry,
            shutdown,
            last_spawn: Arc::new(Mutex::new(Instant::now() - Duration::from_secs(3600))),
            workers_spawned: Arc::new(AtomicU32::new(0)),
        }
    }

    /// Run the supervisor main loop.
    ///
    /// This method runs until the shutdown flag is set. It polls the ready queue
    /// and heartbeat files at the configured intervals, spawning workers when:
    ///
    /// 1. Ready beads exist in the queue
    /// 2. Fleet is idle (all workers exhausted or no active workers)
    /// 3. Active worker count is below the cap
    /// 4. Backoff period has elapsed since last spawn
    ///
    /// # Errors
    ///
    /// Returns an error if:
    /// - The heartbeat directory cannot be read
    /// - The ready queue check fails
    /// - A worker cannot be spawned
    pub async fn run(&self) -> Result<()> {
        self.telemetry.emit(
            crate::telemetry::EventKind::SupervisorStarted,
            [("config", format!("{:?}", self.config))].into_iter().collect(),
        );

        let mut consecutive_empty_cycles = 0u32;
        let heartbeat_ttl = Duration::from_secs(300); // 5 minutes default TTL

        loop {
            if self.shutdown.load(Ordering::Relaxed) {
                tracing::info!("shutdown flag set, supervisor exiting");
                self.telemetry.emit(
                    crate::telemetry::EventKind::SupervisorStopped,
                    [("reason", "shutdown_flag")].into_iter().collect(),
                );
                break;
            }

            // Get current fleet state from heartbeats
            let fleet = self.get_fleet_state(heartbeat_ttl).await?;

            // Check the ready queue
            let queue = self.check_ready_queue().await?;

            tracing::debug!(
                active = fleet.active_count,
                idle = fleet.idle_count,
                busy = fleet.busy_count,
                ready = queue.ready_count,
                "supervisor cycle"
            );

            // Decide whether to spawn a worker
            let should_spawn = self.should_spawn(&queue, &fleet);

            if should_spawn {
                match self.spawn_worker().await {
                    Ok(_) => {
                        let spawned = self.workers_spawned.fetch_add(1, Ordering::Relaxed) + 1;
                        tracing::info!(
                            ready = queue.ready_count,
                            total_spawned = spawned,
                            "supervisor spawned worker"
                        );
                        self.telemetry.emit(
                            crate::telemetry::EventKind::SupervisorWorkerSpawned,
                            [
                                ("ready_count", queue.ready_count.to_string()),
                                ("total_spawned", spawned.to_string()),
                            ]
                            .into_iter()
                            .collect(),
                        );
                        consecutive_empty_cycles = 0;
                    }
                    Err(e) => {
                        tracing::error!(error = %e, "failed to spawn worker");
                        self.telemetry.emit(
                            crate::telemetry::EventKind::SupervisorSpawnFailed,
                            [("error", e.to_string())].into_iter().collect(),
                        );
                    }
                }
            } else {
                // Track consecutive empty cycles for adaptive polling
                if queue.ready_count == 0 && fleet.is_idle {
                    consecutive_empty_cycles =
                        consecutive_empty_cycles.saturating_add(1);
                } else {
                    consecutive_empty_cycles = 0;
                }
            }

            // Adaptive polling: poll faster when active, slower when idle
            let poll_interval = if fleet.is_idle && queue.ready_count == 0 {
                // Idle fleet, no work: poll slowly
                Duration::from_secs(self.config.poll_interval_idle_secs)
            } else {
                // Active fleet or work available: poll more frequently
                Duration::from_secs(self.config.poll_interval_active_secs)
            };

            // Sleep with interruption check
            let sleep_start = Instant::now();
            while sleep_start.elapsed() < poll_interval {
                if self.shutdown.load(Ordering::Relaxed) {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(100)).await;
            }

            // Emit periodic status telemetry
            if consecutive_empty_cycles > 0 && consecutive_empty_cycles % 10 == 0 {
                self.telemetry.emit(
                    crate::telemetry::EventKind::SupervisorIdleCycle,
                    [
                        ("consecutive_empty", consecutive_empty_cycles.to_string()),
                        ("fleet_idle", fleet.is_idle.to_string()),
                    ]
                    .into_iter()
                    .collect(),
                );
            }
        }

        Ok(())
    }

    /// Check the ready queue for beads.
    ///
    /// Runs `br ready --json` and parses the output to count ready beads.
    async fn check_ready_queue(&self) -> Result<ReadyQueueState> {
        let output = tokio::process::Command::new("br")
            .args(["ready", "--json"])
            .current_dir(&self.config.workspace)
            .output()
            .await
            .context("failed to run 'br ready --json'")?;

        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            return Err(anyhow::anyhow!(
                "'br ready --json' failed: {}",
                stderr
            ));
        }

        let stdout = String::from_utf8_lossy(&output.stdout);
        let beads: Vec<BeadId> = stdout
            .lines()
            .filter(|line| !line.is_empty())
            .filter_map(|line| serde_json::from_str::<BeadId>(line).ok())
            .collect();

        Ok(ReadyQueueState {
            ready_count: beads.len(),
            ready_beads: beads,
            checked_at: Utc::now(),
        })
    }

    /// Get fleet state from heartbeat files.
    ///
    /// Reads heartbeat files from the configured directory and computes the
    /// fleet state (active, idle, busy workers). Stale heartbeats are filtered
    /// out based on the TTL.
    async fn get_fleet_state(&self, ttl: Duration) -> Result<FleetState> {
        let heartbeats = HealthMonitor::read_all_heartbeats(&self.config.heartbeat_dir)?;

        let now = Utc::now();
        let mut active_workers = Vec::new();
        let mut idle_count = 0usize;
        let mut busy_count = 0usize;

        for hb in heartbeats {
            // Skip stale heartbeats
            let age = now
                .signed_duration_since(hb.last_heartbeat)
                .to_std()
                .unwrap_or(Duration::ZERO);
            if age > ttl {
                continue;
            }

            // Check if PID is alive
            if !HealthMonitor::check_pid_alive(hb.pid) {
                continue;
            }

            active_workers.push(hb.qualified_id.clone());

            // Count idle vs busy workers
            // A worker is idle if it's exhausted or has no current bead
            let is_idle = hb.is_idle || hb.current_bead.is_none();
            if is_idle {
                idle_count += 1;
            } else {
                busy_count += 1;
            }
        }

        let active_count = active_workers.len();
        let is_idle = active_count == 0 || idle_count == active_count;

        Ok(FleetState {
            active_count,
            idle_count,
            busy_count,
            is_idle,
            active_workers,
            computed_at: now,
        })
    }

    /// Decide whether to spawn a worker.
    ///
    /// Returns true if all conditions are met:
    /// 1. Ready beads exist in the queue
    /// 2. Fleet is idle (all workers exhausted or no active workers)
    /// 3. Active worker count is below the cap
    /// 4. Backoff period has elapsed since last spawn
    fn should_spawn(&self, queue: &ReadyQueueState, fleet: &FleetState) -> bool {
        // Condition 1: Ready beads must exist
        if queue.ready_count == 0 {
            tracing::debug!("no ready beads, skipping spawn");
            return false;
        }

        // Condition 2: Fleet must be idle (all workers exhausted)
        if !fleet.is_idle {
            tracing::debug!(
                idle = fleet.idle_count,
                active = fleet.active_count,
                "fleet not idle, skipping spawn"
            );
            return false;
        }

        // Condition 3: Must be below the worker cap
        if fleet.active_count >= self.config.max_workers as usize {
            tracing::debug!(
                active = fleet.active_count,
                cap = self.config.max_workers,
                "at worker cap, skipping spawn"
            );
            return false;
        }

        // Condition 4: Backoff period must have elapsed
        let last_spawn_guard = self.last_spawn.lock().unwrap();
        let since_last_spawn = last_spawn_guard.elapsed();
        drop(last_spawn_guard);

        let backoff = Duration::from_secs(self.config.spawn_backoff_secs);
        if since_last_spawn < backoff {
            tracing::debug!(
                since_last_secs = since_last_spawn.as_secs(),
                backoff_secs = backoff.as_secs(),
                "in backoff period, skipping spawn"
            );
            return false;
        }

        tracing::info!(
            ready = queue.ready_count,
            active = fleet.active_count,
            cap = self.config.max_workers,
            "conditions met, will spawn worker"
        );
        true
    }

    /// Spawn a new worker.
    ///
    /// Runs `needle run` in the background as a detached process.
    async fn spawn_worker(&self) -> Result<()> {
        // Update last spawn time
        {
            let mut last_spawn = self.last_spawn.lock().unwrap();
            *last_spawn = Instant::now();
        }

        // Build the command
        let mut cmd = Command::new(&self.config.needle_binary);
        cmd.arg("run")
            .current_dir(&self.config.workspace)
            .args(&self.config.worker_args);

        tracing::debug!(
            binary = %self.config.needle_binary.display(),
            workspace = %self.config.workspace.display(),
            args = ?self.config.worker_args,
            "spawning worker"
        );

        // Spawn the process
        #[cfg(unix)]
        {
            use std::os::unix::process::CommandExt;
            unsafe {
                cmd.pre_exec(|| {
                    // Detach from parent process group
                    // This ensures the worker continues running even if the supervisor dies
                    Ok(())
                });
            }
        }

        let child = cmd
            .spawn()
            .context(format!("failed to spawn worker: {:?}", cmd))?;

        // Let the process run in the background
        tracing::debug!(pid = child.id(), "worker spawned");

        Ok(())
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Tests
// ──────────────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Arc;

    #[test]
    fn supervisor_config_default_is_valid() {
        let config = SupervisorConfig::default();
        assert!(config.max_workers > 0);
        assert!(config.poll_interval_active_secs > 0);
        assert!(config.poll_interval_idle_secs > 0);
        assert!(config.spawn_backoff_secs > 0);
    }

    #[test]
    fn fleet_state_empty_is_idle() {
        let state = FleetState::empty();
        assert_eq!(state.active_count, 0);
        assert_eq!(state.idle_count, 0);
        assert_eq!(state.busy_count, 0);
        assert!(state.is_idle);
    }

    #[test]
    fn should_spawn_returns_false_when_no_ready_beads() {
        let config = SupervisorConfig::default();
        let telemetry = Telemetry::new("test".to_string());
        let shutdown = Arc::new(AtomicBool::new(false));
        let supervisor = Supervisor::new(config, telemetry, shutdown);

        let queue = ReadyQueueState {
            ready_count: 0,
            ready_beads: Vec::new(),
            checked_at: Utc::now(),
        };

        let fleet = FleetState::empty();

        assert!(!supervisor.should_spawn(&queue, &fleet));
    }

    #[test]
    fn should_spawn_returns_false_when_fleet_not_idle() {
        let config = SupervisorConfig::default();
        let telemetry = Telemetry::new("test".to_string());
        let shutdown = Arc::new(AtomicBool::new(false));
        let supervisor = Supervisor::new(config, telemetry, shutdown);

        let queue = ReadyQueueState {
            ready_count: 5,
            ready_beads: vec![BeadId::from("needle-1")],
            checked_at: Utc::now(),
        };

        let fleet = FleetState {
            active_count: 2,
            idle_count: 1,
            busy_count: 1,
            is_idle: false, // Fleet not idle
            active_workers: vec!["worker-1".to_string(), "worker-2".to_string()],
            computed_at: Utc::now(),
        };

        assert!(!supervisor.should_spawn(&queue, &fleet));
    }

    #[test]
    fn should_spawn_returns_true_when_all_conditions_met() {
        let mut config = SupervisorConfig::default();
        config.spawn_backoff_secs = 0; // No backoff for test
        config.max_workers = 10;

        let telemetry = Telemetry::new("test".to_string());
        let shutdown = Arc::new(AtomicBool::new(false));
        let supervisor = Supervisor::new(config, telemetry, shutdown);

        let queue = ReadyQueueState {
            ready_count: 5,
            ready_beads: vec![BeadId::from("needle-1")],
            checked_at: Utc::now(),
        };

        let fleet = FleetState {
            active_count: 2,
            idle_count: 2,
            busy_count: 0,
            is_idle: true, // Fleet is idle
            active_workers: vec!["worker-1".to_string(), "worker-2".to_string()],
            computed_at: Utc::now(),
        };

        assert!(supervisor.should_spawn(&queue, &fleet));
    }

    #[test]
    fn should_spawn_returns_false_when_at_worker_cap() {
        let mut config = SupervisorConfig::default();
        config.spawn_backoff_secs = 0;
        config.max_workers = 2;

        let telemetry = Telemetry::new("test".to_string());
        let shutdown = Arc::new(AtomicBool::new(false));
        let supervisor = Supervisor::new(config, telemetry, shutdown);

        let queue = ReadyQueueState {
            ready_count: 5,
            ready_beads: vec![BeadId::from("needle-1")],
            checked_at: Utc::now(),
        };

        let fleet = FleetState {
            active_count: 2, // At cap
            idle_count: 2,
            busy_count: 0,
            is_idle: true,
            active_workers: vec!["worker-1".to_string(), "worker-2".to_string()],
            computed_at: Utc::now(),
        };

        assert!(!supervisor.should_spawn(&queue, &fleet));
    }

    #[tokio::test]
    async fn get_fleet_state_handles_nonexistent_directory() {
        let config = SupervisorConfig {
            heartbeat_dir: PathBuf::from("/nonexistent/path"),
            ..Default::default()
        };
        let telemetry = Telemetry::new("test".to_string());
        let shutdown = Arc::new(AtomicBool::new(false));
        let supervisor = Supervisor::new(config, telemetry, shutdown);

        let state = supervisor
            .get_fleet_state(Duration::from_secs(300))
            .await
            .unwrap();

        assert_eq!(state.active_count, 0);
        assert!(state.is_idle);
    }
}

